const message = $json.body?.message ?? $json.message ?? $json.text ?? "";
const regex = /([1-9A-HJ-NP-Za-km-z]{32,44})/g;
const matches = message.match(regex);

if (!matches || matches.length === 0) {
  return [{
    json: {
      status: "ignored",
      reason: "No token address found"
    }
  }];
}

return [{
  json: {
    status: "parsed",
    tokenAddress: matches[0],
    sourceChannel: $json.body?.channel ?? $json.channel ?? "unknown",
    timestamp: Date.now(),
    rawMessage: message
  }
}];

const duplicate = $json.duplicateValue !== null && $json.duplicateValue !== undefined;
const dailyCount = Math.max(
  Number($json.dailyCountValue ?? 0),
  Number($json.trades_executed_today ?? 0)
);
const circuitBreakerActive = Boolean($json.circuitBreakerValue) || Boolean($json.circuit_breaker_active);
const openPositions = Math.max(
  Number($json.open_positions_count ?? 0),
  Number($json.openPositionsCount ?? 0)
);

if (duplicate) {
  return [{ json: { ...$json, status: "duplicate", reason: "Token already seen in Redis" } }];
}

if (dailyCount >= 200) {
  return [{ json: { ...$json, status: "daily_limit_reached", reason: "Daily trade limit reached", dailyCount } }];
}

if (circuitBreakerActive) {
  return [{ json: { ...$json, status: "circuit_breaker_active", reason: "Circuit breaker is active" } }];
}

if (openPositions >= 3) {
  return [{ json: { ...$json, status: "queue", reason: "Open position cap reached", openPositions } }];
}

return [{
  json: {
    ...$json,
    status: "approved",
    dailyPnL: Number($json.daily_pnl ?? 0),
    consecutiveLosses: Number($json.consecutive_losses ?? 0),
    dailyCount,
    openPositions
  }
}];

const tokenAddress = $json.tokenAddress;
const timeoutMs = 800;

const checks = await Promise.allSettled([
  apiCallWithRetry(`https://api.rugcheck.xyz/v1/tokens/${tokenAddress}/report`, {
    headers: { Authorization: `Bearer ${$env.RUGCHECK_API_KEY ?? ""}` }
  }).then((data) => ({ source: "rugcheck", tokenAddress, ...data })),
  apiCallWithRetry(`https://api.gopluslabs.io/api/v1/token_security/solana?contract_addresses=${tokenAddress}`, {
    headers: { Authorization: `Bearer ${$env.GOPLUS_API_KEY ?? ""}` }
  }).then((data) => ({ source: "goplus", tokenAddress, ...data })),
  apiCallWithRetry(`https://api.solsniffer.com/v2/token/${tokenAddress}`, {
    headers: { "X-API-KEY": $env.SOLSNIFFER_API_KEY ?? "" }
  }).then((data) => ({ source: "solsniffer", tokenAddress, ...data }))
]);

const results = checks
  .filter((check) => check.status === "fulfilled")
  .map((check) => check.value);

if (results.length < 2) {
  return [{
    json: {
      status: "abort",
      reason: "Insufficient security data",
      tokenAddress,
      failedAPIs: checks.filter((check) => check.status === "rejected").length
    }
  }];
}

const securityScore = Object.fromEntries(
  results.map((result) => [result.source, evaluateResult(result)])
);

const passedChecks = Object.values(securityScore).filter(Boolean).length;

if (passedChecks === results.length) {
  return [{ json: { status: "safe", tokenAddress, securityScore, results } }];
}

return [{
  json: {
    status: "abort",
    reason: "Security check failed",
    tokenAddress,
    securityScore,
    results
  }
}];

async function apiCallWithRetry(url, options = {}, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt += 1) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(url, { ...options, signal: controller.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } catch (error) {
      if (attempt === maxRetries - 1) throw error;
      await new Promise((resolve) => setTimeout(resolve, 2 ** attempt * 100));
    } finally {
      clearTimeout(timeout);
    }
  }
}

function evaluateResult(result) {
  if (result.source === "rugcheck") {
    return Number(result.score ?? Infinity) < 500 && result.token?.liquidityBurned === true;
  }

  if (result.source === "goplus") {
    const data = result.data?.[tokenAddress] ?? result.result?.[tokenAddress] ?? result.data;
    return isFalseLike(data?.is_mintable) && isFalseLike(data?.is_freezable) && isFalseLike(data?.is_honeypot);
  }

  if (result.source === "solsniffer") {
    const top10 = Number(result.topHolders?.top10Percentage ?? result.top10Percentage ?? 100);
    return top10 <= 25;
  }

  return false;
}

function isFalseLike(value) {
  return value === false || value === "0" || value === 0 || value === "false";
}

const pairs = Array.isArray($json.pairs) ? $json.pairs : [];
const pair = pairs
  .filter((item) => item.chainId === "solana")
  .sort((a, b) => Number(b.liquidity?.usd ?? 0) - Number(a.liquidity?.usd ?? 0))[0];

if (!pair) {
  return [{
    json: {
      ...$json,
      marketStatus: "missing",
      market: {},
      riskSignals: { negativeCount: 0, source: "market_unavailable" }
    }
  }];
}

const buys5m = Number(pair.txns?.m5?.buys ?? 0);
const sells5m = Number(pair.txns?.m5?.sells ?? 0);
const createdAt = Number(pair.pairCreatedAt ?? 0);
const tokenAgeMinutes = createdAt > 0 ? Math.max(0, (Date.now() - createdAt) / 60000) : 0;

return [{
  json: {
    ...$json,
    marketStatus: "ok",
    market: {
      dexId: pair.dexId,
      pairAddress: pair.pairAddress,
      url: pair.url,
      priceUsd: Number(pair.priceUsd ?? 0),
      liquidityUsd: Number(pair.liquidity?.usd ?? 0),
      volume5mUsd: Number(pair.volume?.m5 ?? 0),
      volume24hUsd: Number(pair.volume?.h24 ?? 0),
      holderCount: Number(pair.info?.holders ?? 0),
      top10HolderPercentage: Number(pair.info?.top10HolderPercentage ?? 100),
      buyPressure: buys5m,
      sellPressure: sells5m,
      tokenAgeMinutes
    },
    metrics: {
      currentPrice: Number(pair.priceUsd ?? 0),
      volume24h: Number(pair.volume?.h24 ?? 0),
      holdersCount: Number(pair.info?.holders ?? 0),
      buyPressure: buys5m,
      sellPressure: sells5m,
      networkFees: 0
    },
    riskSignals: { negativeCount: 0, source: "market_snapshot" }
  }
}];

const features = buildLearningFeatures({
  securityScore: $json.securityScore,
  market: $json.market,
  risk: $json.riskSignals
});

const patternKey = buildPatternKey(features);

return [{
  json: {
    ...$json,
    learningFeatures: features,
    patternKey,
    securitySnapshot: JSON.stringify(features.security),
    marketSnapshot: JSON.stringify(features.market),
    riskSnapshot: JSON.stringify(features.risk)
  }
}];

function buildLearningFeatures(input = {}) {
  const securityScore = input.securityScore ?? {};
  const market = input.market ?? {};
  const risk = input.risk ?? {};

  return {
    featureVersion: "v1.1",
    security: {
      rugcheck: Boolean(securityScore.rugcheck),
      goplus: Boolean(securityScore.goplus),
      solsniffer: Boolean(securityScore.solsniffer)
    },
    market: {
      liquidityUsd: Number(market.liquidityUsd ?? 0),
      volume5mUsd: Number(market.volume5mUsd ?? 0),
      volume24hUsd: Number(market.volume24hUsd ?? 0),
      holderCount: Number(market.holderCount ?? 0),
      top10HolderPercentage: Number(market.top10HolderPercentage ?? 100),
      buyPressure: Number(market.buyPressure ?? 0),
      sellPressure: Number(market.sellPressure ?? 0),
      tokenAgeMinutes: Number(market.tokenAgeMinutes ?? 0)
    },
    risk: {
      negativeCount: Number(risk.negativeCount ?? 0),
      source: risk.source ?? "unknown"
    }
  };
}

function buildPatternKey(features) {
  const pressureRatio = features.market.sellPressure / (features.market.buyPressure || 1);
  return [
    `liq:${bucket(features.market.liquidityUsd, [1000, 5000, 10000, 25000, 50000])}`,
    `vol5:${bucket(features.market.volume5mUsd, [500, 2500, 5000, 10000, 25000])}`,
    `holders:${bucket(features.market.holderCount, [25, 75, 150, 300, 600])}`,
    `top10:${bucket(features.market.top10HolderPercentage, [10, 20, 25, 35, 50])}`,
    `age:${bucket(features.market.tokenAgeMinutes, [5, 15, 30, 60, 180])}`,
    `sellbuy:${bucket(pressureRatio, [0.5, 1, 2, 3, 5])}`,
    `risk:${bucket(features.risk.negativeCount, [0, 1, 2, 3])}`
  ].join("|");
}

function bucket(value, thresholds) {
  for (const threshold of thresholds) {
    if (Number(value) <= threshold) return `lte_${threshold}`;
  }
  return `gt_${thresholds[thresholds.length - 1]}`;
}

const patternKey = $json.patternKey;

if (!patternKey) {
  return [{ json: { ...$json, learningAction: "neutral", learningReason: "No pattern key" } }];
}

const pattern = $json.learningPattern ?? $json;
const decision = scorePattern(pattern);

if (decision.action === "block_or_reduce") {
  return [{
    json: {
      ...$json,
      learningAction: "reduce",
      betSizeUsd: Math.max(0.1, Number($json.betSizeUsd ?? 0.25) * 0.5),
      learningReason: decision.reason,
      confidenceScore: decision.confidenceScore
    }
  }];
}

return [{
  json: {
    ...$json,
    learningAction: decision.action,
    learningReason: decision.reason,
    confidenceScore: decision.confidenceScore
  }
}];

function scorePattern(pattern = {}) {
  const sampleCount = Number(pattern.sample_count ?? 0);
  const winCount = Number(pattern.win_count ?? 0);
  const totalPnlUsd = Number(pattern.total_pnl_usd ?? 0);
  const avgMaxMultiplier = Number(pattern.avg_max_multiplier ?? 0);

  if (sampleCount < 5) {
    return { action: "neutral", confidenceScore: 0, reason: "Insufficient samples" };
  }

  const winRate = winCount / sampleCount;
  const pnlPerTrade = totalPnlUsd / sampleCount;
  const confidenceScore = round((winRate - 0.5) * 2 + pnlPerTrade + Math.min(avgMaxMultiplier, 10) / 10);

  if (confidenceScore <= -0.5) {
    return { action: "block_or_reduce", confidenceScore, reason: "Pattern has negative historical expectancy" };
  }

  if (confidenceScore >= 0.8) {
    return { action: "allow", confidenceScore, reason: "Pattern has positive historical expectancy" };
  }

  return { action: "neutral", confidenceScore, reason: "Pattern is inconclusive" };
}

function round(value) {
  return Math.round(value * 10000) / 10000;
}

const dailyPnL = Number($json.dailyPnL ?? 0);
const consecutiveLosses = Number($json.consecutiveLosses ?? 0);

let betSizeUsd = 0.25;

if (dailyPnL <= -15 || consecutiveLosses >= 15) {
  return [{
    json: {
      ...$json,
      action: "HALT",
      reason: "Circuit breaker activated",
      betSizeUsd: 0
    }
  }];
}

if (dailyPnL < -10) betSizeUsd = 0.15;
if (dailyPnL < -20) betSizeUsd = 0.10;
if (consecutiveLosses >= 5) betSizeUsd *= 0.8;
if (consecutiveLosses >= 10) betSizeUsd *= 0.5;

return [{
  json: {
    ...$json,
    action: "TRADE",
    betSizeUsd: Math.round(betSizeUsd * 100) / 100
  }
}];

const solUsd = Number($json.solUsd ?? $env.SOL_USD);
const betSizeUsd = Number($json.betSizeUsd ?? 0.25);

if (!Number.isFinite(solUsd) || solUsd <= 0) {
  return [{ json: { ...$json, status: "sol_price_missing", reason: "Set SOL_USD in n8n environment" } }];
}

const lamportsAmount = Math.max(1, Math.floor((betSizeUsd / solUsd) * 1_000_000_000));
const quoteUrl = new URL("https://quote-api.jup.ag/v6/quote");
quoteUrl.searchParams.set("inputMint", "So11111111111111111111111111111111111111112");
quoteUrl.searchParams.set("outputMint", $json.tokenAddress);
quoteUrl.searchParams.set("amount", String(lamportsAmount));
quoteUrl.searchParams.set("slippageBps", String(Number($env.JUPITER_SLIPPAGE_BPS ?? 1500)));

return [{ json: { ...$json, status: "quote_requested", betSizeUsd, solUsd, lamportsAmount, quoteUrl: quoteUrl.toString() } }];

const quote = $json.outAmount ? $json : ($json.quote ?? {});
const userPublicKey = $env.SOLANA_WALLET_PUBLIC_KEY;

if (!userPublicKey) {
  return [{ json: { ...$json, status: "wallet_missing", reason: "Set SOLANA_WALLET_PUBLIC_KEY" } }];
}

if (!quote.outAmount || !quote.inAmount) {
  return [{ json: { ...$json, status: "quote_failed", reason: $json.error ?? "Jupiter quote did not return amounts" } }];
}

return [{
  json: {
    ...$json,
    status: "swap_requested",
    quote,
    entryPrice: Number(quote.outAmount) / Number(quote.inAmount),
    outputAmount: quote.outAmount,
    swapUrl: "https://quote-api.jup.ag/v6/swap",
    swapPayload: {
      quoteResponse: quote,
      userPublicKey,
      wrapAndUnwrapSol: true,
      dynamicComputeUnitLimit: true,
      prioritizationFeeLamports: {
        priorityLevelWithMaxLamports: {
          maxLamports: Number($env.JUPITER_MAX_PRIORITY_LAMPORTS ?? 10000000),
          priorityLevel: "veryHigh"
        }
      }
    }
  }
}];

const serializedTransaction = $json.swapTransaction ?? $json.serializedTransaction;

if (!serializedTransaction) {
  return [{ json: { ...$json, status: "swap_build_failed", reason: $json.error ?? "Jupiter did not return swapTransaction" } }];
}

return [{
  json: {
    ...$json,
    status: "swap_ready",
    serializedTransaction,
    signerUrl: $env.SIGNER_URL ?? "",
    signerApiKey: $env.SIGNER_API_KEY ?? "",
    timestamp: Date.now()
  }
}];

if (!$json.signerUrl) {
  return [{
    json: {
      ...$json,
      status: "paper_swap_ready",
      reason: "SIGNER_URL not configured; transaction built but not signed"
    }
  }];
}

return [{
  json: {
    ...$json,
    signerPayload: {
      action: $json.signerAction ?? "buy",
      tokenAddress: $json.tokenAddress,
      serializedTransaction: $json.serializedTransaction,
      expectedOutputAmount: $json.outputAmount,
      positionId: $json.positionId ?? null
    }
  }
}];

if ($json.status === "paper_swap_ready") {
  return [{ json: $json }];
}

const txHash = $json.txHash ?? $json.signature ?? $json.transactionHash;
if (!txHash) {
  return [{ json: { ...$json, status: "signer_failed", reason: $json.error ?? "Signer did not return a transaction hash" } }];
}

return [{
  json: {
    ...$json,
    status: $json.signerAction === "sell" ? "sold" : "bought",
    txHash,
    entryAmount: $json.amount ?? $json.outputAmount,
    signedAt: Date.now()
  }
}];

const position = {
  id: $json.id,
  tokenAddress: $json.token_address ?? $json.tokenAddress,
  entryPrice: Number($json.entry_price ?? $json.entryPrice),
  entryAmount: Number($json.entry_amount ?? $json.entryAmount),
  highestPrice: Number($json.highest_price ?? $json.highestPrice ?? $json.entry_price ?? $json.entryPrice),
  partialTPTaken: Boolean($json.partial_tp_taken ?? $json.partialTPTaken),
  avgVolume: Number($json.avg_volume ?? $json.avgVolume ?? 0),
  peakHolders: Number($json.peak_holders ?? $json.peakHolders ?? 0),
  createdAt: $json.created_at ?? $json.createdAt
};

return [{ json: { position, tokenAddress: position.tokenAddress } }];

const pairs = Array.isArray($json.pairs) ? $json.pairs : [];
const pair = pairs
  .filter((item) => item.chainId === "solana")
  .sort((a, b) => Number(b.liquidity?.usd ?? 0) - Number(a.liquidity?.usd ?? 0))[0];

if (!pair) {
  return [{
    json: {
      ...$json,
      marketStatus: "missing",
      market: {},
      riskSignals: { negativeCount: 0, source: "market_unavailable" }
    }
  }];
}

const buys5m = Number(pair.txns?.m5?.buys ?? 0);
const sells5m = Number(pair.txns?.m5?.sells ?? 0);
const createdAt = Number(pair.pairCreatedAt ?? 0);
const tokenAgeMinutes = createdAt > 0 ? Math.max(0, (Date.now() - createdAt) / 60000) : 0;

return [{
  json: {
    ...$json,
    marketStatus: "ok",
    market: {
      dexId: pair.dexId,
      pairAddress: pair.pairAddress,
      url: pair.url,
      priceUsd: Number(pair.priceUsd ?? 0),
      liquidityUsd: Number(pair.liquidity?.usd ?? 0),
      volume5mUsd: Number(pair.volume?.m5 ?? 0),
      volume24hUsd: Number(pair.volume?.h24 ?? 0),
      holderCount: Number(pair.info?.holders ?? 0),
      top10HolderPercentage: Number(pair.info?.top10HolderPercentage ?? 100),
      buyPressure: buys5m,
      sellPressure: sells5m,
      tokenAgeMinutes
    },
    metrics: {
      currentPrice: Number(pair.priceUsd ?? 0),
      volume24h: Number(pair.volume?.h24 ?? 0),
      holdersCount: Number(pair.info?.holders ?? 0),
      buyPressure: buys5m,
      sellPressure: sells5m,
      networkFees: 0
    },
    riskSignals: { negativeCount: 0, source: "market_snapshot" }
  }
}];

const position = $json.position;
const metrics = $json.metrics;
const currentPrice = Number(metrics.currentPrice);
const entryPrice = Number(position.entryPrice ?? position.entry_price);
const highestPrice = Math.max(Number(position.highestPrice ?? position.highest_price ?? currentPrice), currentPrice);
const multiplier = currentPrice / entryPrice;

const riskSignals = analyzeLocally(metrics, position);
if (riskSignals.negativeCount >= 3) {
  return [{
    json: {
      action: "panic_exit",
      reason: riskSignals.reasons,
      riskSignals,
      positionId: position.id
    }
  }];
}

const stop = calculateTrailingStop(position, currentPrice, highestPrice);
if (stop.action === "full_exit") {
  return [{
    json: {
      action: "trailing_stop_exit",
      reason: `Price ${currentPrice} <= stop ${stop.price}`,
      stop,
      riskSignals,
      positionId: position.id
    }
  }];
}

if (stop.action === "partial_exit") {
  return [{
    json: {
      action: "partial_take_profit",
      amount: "50%",
      stop,
      riskSignals,
      positionId: position.id
    }
  }];
}

return [{
  json: {
    action: "hold",
    positionId: position.id,
    highestPrice,
    multiplier,
    stop,
    riskSignals
  }
}];

function analyzeLocally(metrics, position) {
  const signals = [];

  if (Number(position.avgVolume ?? 0) > 0 && Number(metrics.volume24h ?? 0) < Number(position.avgVolume) * 0.5) {
    signals.push("volume_decline");
  }

  if (Number(position.peakHolders ?? 0) > 0 && Number(metrics.holdersCount ?? 0) < Number(position.peakHolders) * 0.9) {
    signals.push("holder_drop");
  }

  const sellPressure = Number(metrics.sellPressure ?? 0) / (Number(metrics.buyPressure ?? 0) || 1);
  if (sellPressure > 3) signals.push("sell_pressure_spike");

  if (Number(metrics.networkFees ?? 0) > 100000) signals.push("network_congestion");

  return {
    negativeCount: signals.length,
    signals,
    reasons: signals.join(", "),
    source: "local_engine"
  };
}

function calculateTrailingStop(position, currentPrice, highestPrice) {
  const entryPrice = Number(position.entryPrice ?? position.entry_price);
  const multiplier = currentPrice / entryPrice;
  const stopLossPrice = entryPrice * 0.34;

  if (currentPrice <= stopLossPrice) {
    return { type: "hard_stop_loss", action: "full_exit", price: stopLossPrice, multiplier };
  }

  const partialTPTaken = Boolean(position.partialTPTaken ?? position.partial_tp_taken);
  if (multiplier >= 2 && !partialTPTaken) {
    return { type: "partial_take_profit", action: "partial_exit", amount: "50%", multiplier: 2 };
  }

  if (multiplier <= 2) {
    return { type: "stop_loss_only", action: "hold", price: stopLossPrice, multiplier };
  }

  const percentage = multiplier <= 10
    ? 20 + (multiplier - 2) * 1.5
    : Math.min(32 + (multiplier - 10) * 2.5, 55);

  const price = highestPrice * (1 - percentage / 100);
  return {
    type: "trailing_stop",
    action: currentPrice <= price ? "full_exit" : "hold",
    price,
    percentage,
    highestPrice,
    multiplier
  };
}

const position = $json.position;
const currentAmount = Number(position.entryAmount ?? position.entry_amount ?? 0);
const tokenAmount = Number($json.exitAmount ?? ($json.action === "partial_take_profit" ? currentAmount * 0.5 : currentAmount));

if (!Number.isFinite(tokenAmount) || tokenAmount <= 0) {
  return [{ json: { ...$json, status: "sell_amount_missing", reason: "Position entry amount is missing" } }];
}

const quoteUrl = new URL("https://quote-api.jup.ag/v6/quote");
quoteUrl.searchParams.set("inputMint", position.tokenAddress ?? position.token_address);
quoteUrl.searchParams.set("outputMint", "So11111111111111111111111111111111111111112");
quoteUrl.searchParams.set("amount", String(Math.floor(tokenAmount)));
quoteUrl.searchParams.set("slippageBps", String(Number($env.JUPITER_EXIT_SLIPPAGE_BPS ?? 2000)));

return [{
  json: {
    ...$json,
    signerAction: "sell",
    status: "sell_quote_requested",
    exitAmount: Math.floor(tokenAmount),
    quoteUrl: quoteUrl.toString()
  }
}];

const quote = $json.outAmount ? $json : ($json.quote ?? {});
const userPublicKey = $env.SOLANA_WALLET_PUBLIC_KEY;

if (!userPublicKey) {
