      wrapAndUnwrapSol: true,
      dynamicComputeUnitLimit: true,
      prioritizationFeeLamports: {
        priorityLevelWithMaxLamports: {
          maxLamports: Number($env.JUPITER_MAX_PRIORITY_LAMPORTS ?? 10000000),
          priorityLevel: "veryHigh"
        }
      }
    }
  }
}];

const serializedTransaction = $json.swapTransaction ?? $json.serializedTransaction;

if (!serializedTransaction) {
  return [{ json: { ...$json, status: "swap_build_failed", reason: $json.error ?? "Jupiter did not return swapTransaction" } }];
}

return [{
  json: {
    ...$json,
    status: "swap_ready",
    serializedTransaction,
    signerUrl: $env.SIGNER_URL ?? "",
    signerApiKey: $env.SIGNER_API_KEY ?? "",
    timestamp: Date.now()
  }
}];

if (!$json.signerUrl) {
  return [{
    json: {
      ...$json,
      status: "paper_swap_ready",
      reason: "SIGNER_URL not configured; transaction built but not signed"
    }
  }];
}

return [{
  json: {
    ...$json,
    signerPayload: {
      action: $json.signerAction ?? "buy",
      tokenAddress: $json.tokenAddress,
      serializedTransaction: $json.serializedTransaction,
      expectedOutputAmount: $json.outputAmount,
      positionId: $json.positionId ?? null
    }
  }
}];

if ($json.status === "paper_swap_ready") {
  return [{ json: $json }];
}

const txHash = $json.txHash ?? $json.signature ?? $json.transactionHash;
if (!txHash) {
  return [{ json: { ...$json, status: "signer_failed", reason: $json.error ?? "Signer did not return a transaction hash" } }];
}

return [{
  json: {
    ...$json,
    status: $json.signerAction === "sell" ? "sold" : "bought",
    txHash,
    entryAmount: $json.amount ?? $json.outputAmount,
    signedAt: Date.now()
  }
}];

const position = $json.position ?? {};
const entryPrice = Number(position.entryPrice ?? position.entry_price);
const exitPrice = Number($json.exitPrice ?? $json.metrics?.currentPrice ?? position.exit_price);
const finalMultiplier = entryPrice > 0 ? exitPrice / entryPrice : 0;
const maxMultiplier = entryPrice > 0 ? Number(position.highestPrice ?? position.highest_price ?? exitPrice) / entryPrice : finalMultiplier;
const pnlUsd = Number($json.pnlUsd ?? position.pnl_usd ?? 0);
const createdAt = position.createdAt ?? position.created_at ?? Date.now();
const holdTimeSeconds = Math.max(0, Math.floor((Date.now() - new Date(createdAt).getTime()) / 1000));
const wasWinner = pnlUsd > 0 || finalMultiplier >= 2;
const outcomeLabel = labelOutcome({ finalMultiplier, maxMultiplier, pnlUsd });

return [{
  json: {
    ...$json,
    positionId: position.id ?? $json.positionId,
    tokenAddress: position.tokenAddress ?? position.token_address ?? $json.tokenAddress,
    holdTimeSeconds,
    entryPrice,
    exitPrice,
    maxMultiplier,
    finalMultiplier,
    pnlUsd,
    wasWinner,
    outcomeLabel,
    exitReason: $json.exitReason ?? $json.reason ?? $json.action ?? "unknown"
  }
}];

function labelOutcome(outcome = {}) {
  if (Number(outcome.maxMultiplier ?? 0) >= 10) return "moonshot";
  if (Number(outcome.finalMultiplier ?? 0) >= 2 || Number(outcome.pnlUsd ?? 0) > 0) return "winner";
  if (Number(outcome.finalMultiplier ?? 0) <= 0.34) return "hard_loss";
  if (Number(outcome.pnlUsd ?? 0) < 0) return "loser";
  return "flat";
}

const stats = $json.stats ?? $json;

const triggers = [
  { condition: Number(stats.dailyPnL ?? 0) <= -15, reason: "Daily loss limit reached" },
  { condition: Number(stats.consecutiveLosses ?? 0) >= 15, reason: "Consecutive losses limit" },
  { condition: Number(stats.apiFailures ?? 0) > 20, reason: "Excessive API failures" },
  { condition: Number(stats.oldestOpenPositionAgeMs ?? 0) > 45 * 60 * 1000, reason: "Position timeout risk" }
];

const trigger = triggers.find((item) => item.condition);

if (!trigger) {
  return [{ json: { ...$json, status: "healthy" } }];
}

return [{
  json: {
    ...$json,
    status: "halted",
    reason: trigger.reason,
    closeAllPositions: true,
    notifyAdmin: true
  }
}];
